<?php
require_once dirname(__DIR__) . '/_private/bootstrap.php';
page_role('teacher');
require_once dirname(__DIR__) . '/_private/database.php';

$modeLabels=['online'=>'online','email'=>'e-mail','in_person'=>'in person'];
if (($_SERVER['REQUEST_METHOD'] ?? 'GET') === 'POST') {
    require_post(); $action=input_text($_POST,'action');
    if ($action==='save_consultation') {
        $name=input_text($_POST,'name'); $university=input_text($_POST,'university'); $email=input_text($_POST,'email'); $uco=input_text($_POST,'uco'); $content=input_text($_POST,'content'); $mode=input_text($_POST,'mode');
        if ($name==='' || $content==='' || !in_array($mode,array_keys($modeLabels),true) || ($email!=='' && !filter_var($email,FILTER_VALIDATE_EMAIL))) app_error(422,'Please fill in name, content consultations a platný způsob kontaktu.');
        $stmt=$pdo->prepare('SELECT id FROM adhoc_students WHERE (email<>? AND email<>"" AND email IS NOT NULL) OR (name=? AND university=?) ORDER BY id LIMIT 1'); $stmt->execute([$email,$name,$university]); $studentId=(int)($stmt->fetchColumn() ?: 0);
        if ($studentId) { $pdo->prepare('UPDATE adhoc_students SET name=?,university=?,email=?,uco=?,updated_at=NOW() WHERE id=?')->execute([$name,$university,$email,$uco,$studentId]); }
        else { $pdo->prepare('INSERT INTO adhoc_students (name,university,email,uco) VALUES (?,?,?,?)')->execute([$name,$university,$email,$uco]); $studentId=(int)$pdo->lastInsertId(); }
        $pdo->prepare('INSERT INTO adhoc_consultations (student_id,content,mode,consulted_at) VALUES (?,?,?,NOW())')->execute([$studentId,$content,$mode]);
    } elseif ($action==='status') {
        $id=input_id($_POST,'student_id'); $status=input_text($_POST,'status'); if(!in_array($status,['unresolved','ongoing','resolved'],true)) app_error(422,'Invalid stav.');
        $pdo->prepare('UPDATE adhoc_students SET status=? WHERE id=?')->execute([$status,$id]);
    } else app_error(400,'Unknown action.');
    header('Location: /studevid/adhoc/',true,303); exit;
}
$search=input_text($_GET,'search'); $university=input_text($_GET,'university');
$where=[];$params=[]; if($search!==''){ $where[]='s.name LIKE ?';$params[]='%'.$search.'%'; } if($university!==''){ $where[]='s.university LIKE ?';$params[]='%'.$university.'%'; }
$sql='SELECT s.*,COUNT(c.id) AS consultation_count,MAX(c.consulted_at) AS last_consultation FROM adhoc_students s LEFT JOIN adhoc_consultations c ON c.student_id=s.id'; if($where)$sql.=' WHERE '.implode(' AND ',$where); $sql.=' GROUP BY s.id ORDER BY last_consultation DESC,s.name'; $stmt=$pdo->prepare($sql);$stmt->execute($params);$students=$stmt->fetchAll();
$suggestions=$pdo->query('SELECT id,name,university,email,uco FROM adhoc_students ORDER BY name LIMIT 200')->fetchAll();
$universities=$pdo->query("SELECT DISTINCT university FROM adhoc_students WHERE university<>'' ORDER BY university")->fetchAll(PDO::FETCH_COLUMN);
$selected=isset($_GET['student_id']) ? input_id($_GET,'student_id') : 0; $history=[]; if($selected){$stmt=$pdo->prepare('SELECT c.*,s.name,s.university FROM adhoc_consultations c JOIN adhoc_students s ON s.id=c.student_id WHERE c.student_id=? ORDER BY c.consulted_at DESC');$stmt->execute([$selected]);$history=$stmt->fetchAll();}
$globalCssPath='/studevid/css/global.css';$dashboardCssPath=null;$extraCssFiles=[];$loadJquery=false;$loadChartJs=false;$loadDesignJs=false;
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ad hoc consultations</title><?php require dirname(__DIR__).'/_private/views/header.php'; ?><style>.adhoc{max-width:var(--content-width);margin:auto}.status-dot{display:inline-block;width:.7rem;height:.7rem;border-radius:50%;margin-right:.35rem}.unresolved{background:#c62828}.ongoing{background:#f9a825}.resolved{background:#2e7d32}.inline{display:inline}</style></head><body><main class="adhoc"><section class="standardCard" id="new-consultation"><h1>Ad hoc consultations</h1><p class="muted">Records consultations outside the regular list students.</p><form method="post" class="formEdit"><?= csrf_field() ?><input type="hidden" name="action" value="save_consultation"><div class="formRow"><label>Name <input name="name" list="adhoc-students" required></label><label>University <input name="university"></label><label>Email <input name="email" type="email"></label><label>Student ID <input name="uco"></label></div><datalist id="adhoc-students"><?php foreach($suggestions as $s): ?><option value="<?= h($s['name']) ?>" label="<?= h(trim($s['university'].' '.$s['email'])) ?>"></option><?php endforeach; ?></datalist><div class="formRow"><label>Method <select name="mode"><option value="in_person">in person</option><option value="online">online</option><option value="email">by email</option></select></label><label style="display:block">Content consultations<textarea name="content" rows="5" required></textarea></label></div><button class="button-link primary" type="submit">Add konzultaci</button></form></section><section class="standardCard"><h2>Students</h2><form method="get" class="formEdit"><input name="search" placeholder="Name" value="<?= h($search) ?>"><input name="university" list="universities" placeholder="University" value="<?= h($university) ?>"><datalist id="universities"><?php foreach($universities as $u): ?><option><?= h($u) ?></option><?php endforeach; ?></datalist><button class="button-link" type="submit">Filter</button> <a class="button-link subtle" href="/studevid/adhoc/">Cancel filtr</a></form><div class="table-responsive"><table class="schedulerTable"><thead><tr><th>Status</th><th>Name</th><th>University</th><th>Latest consultations</th><th>Count</th><th>Actions</th></tr></thead><tbody><?php foreach($students as $s): ?><tr><td><span class="status-dot <?= h($s['status']) ?>"></span><?= $s['status']==='unresolved'?'unresolved':($s['status']==='ongoing'?'ongoing':'resolved') ?></td><td><?= h($s['name']) ?></td><td><?= h($s['university']) ?></td><td><?= $s['last_consultation']?h(date('j. n. Y H:i',strtotime($s['last_consultation']))):'—' ?></td><td><?= (int)$s['consultation_count'] ?></td><td><a class="button-link subtle" href="?student_id=<?= (int)$s['id'] ?>">History</a> <form method="post" class="inline"><?= csrf_field() ?><input type="hidden" name="action" value="status"><input type="hidden" name="student_id" value="<?= (int)$s['id'] ?>"><select name="status" onchange="this.form.submit()"><option value="unresolved" <?= $s['status']==='unresolved'?'selected':'' ?>>red</option><option value="ongoing" <?= $s['status']==='ongoing'?'selected':'' ?>>yellow</option><option value="resolved" <?= $s['status']==='resolved'?'selected':'' ?>>green</option></select></form></td></tr><?php endforeach; ?></tbody></table></div></section><?php if($selected): ?><section class="standardCard"><h2>History</h2><?php foreach($history as $hrow): ?><article class="info-item"><strong><?= h(date('j. n. Y H:i',strtotime($hrow['consulted_at']))) ?> · <?= h($modeLabels[$hrow['mode']]??$hrow['mode']) ?></strong><p><?= nl2br(h($hrow['content'])) ?></p></article><?php endforeach; ?></section><?php endif; ?><p><a class="button-link" href="/studevid/students.php">← Back na student homepage</a></p></main></body></html>
